218	class KahnTopologicalSort implements TopologicalSortingAlgorithm {
219	    @Override
220	    public TopologicalSortResult sort(GraphStructure graph) {
221	        long startTime = System.currentTimeMillis();
222	
223	        int[] indegree = calculateIndegrees(graph);
224	        Queue<Integer> queue = initializeQueue(graph.getVertexCount(), indegree);
225	        List<Integer> result = new ArrayList<>();
226	
227	        processNodes(queue, graph, indegree, result);
228	
229	        boolean hasCycle = result.size() != graph.getVertexCount();
230	        long executionTime = System.currentTimeMillis() - startTime;
231	
232	        return new TopologicalSortResult(result, graph.getVertexCount(), hasCycle, executionTime);
233	    }
234	
235	    private int[] calculateIndegrees(GraphStructure graph) {
236	        int[] indegree = new int[graph.getVertexCount()];
237	        for (int i = 0; i < graph.getVertexCount(); i++) {
238	            for (int neighbor : graph.getNeighbors(i)) {
239	                indegree[neighbor]++;
240	            }
241	        }
242	        return indegree;
243	    }
244	
245	    private Queue<Integer> initializeQueue(int vertices, int[] indegree) {
246	        Queue<Integer> queue = new LinkedList<>();
247	        for (int i = 0; i < vertices; i++) {
248	            if (indegree[i] == 0) {
249	                queue.add(i);
250	            }
251	        }
252	        return queue;
253	    }
254	
255	    private void processNodes(Queue<Integer> queue, GraphStructure graph,
256	                            int[] indegree, List<Integer> result) {
257	        while (!queue.isEmpty()) {
258	            int node = queue.poll();
259	            result.add(node);
260	
261	            for (int neighbor : graph.getNeighbors(node)) {
262	                indegree[neighbor]--;
263	                if (indegree[neighbor] == 0) {
264	                    queue.add(neighbor);
265	                }
266	            }
267	        }
268	    }
269	}
