271	class DirectedAcyclicGraph {
272	    private final GraphStructure structure;
273	    private TopologicalSortingAlgorithm algorithm;
274	    private TopologicalSortResult cachedResult;
275	    private boolean isLocked = false;
276	    private final List<List<Integer>> adjacencyList;
277	    private final int vertices;
278	    private final Set<String> edgeSet;
279	
280	    public DirectedAcyclicGraph(int vertices) {
281	        this(vertices, new KahnTopologicalSort());
282	    }
283	
284	    public DirectedAcyclicGraph(int vertices, TopologicalSortingAlgorithm algorithm) {
285	        Validator.validatePositive(vertices, "vertices");
286	        Validator.validateNotNull(algorithm, "algorithm");
287	
288	        this.vertices = vertices;
289	        this.adjacencyList = new ArrayList<>();
290	        for (int i = 0; i < vertices; i++) {
291	            this.adjacencyList.add(new ArrayList<>());
292	        }
293	        this.algorithm = algorithm;
294	        this.structure = new GraphStructure(vertices, adjacencyList);
295	        this.edgeSet = new HashSet<>();
296	    }
297	
298	    public void addEdge(int source, int destination) {
299	        if (isLocked) {
300	            throw new IllegalStateException("Cannot modify graph after sorting");
301	        }
302	        Validator.validateInRange(source, 0, vertices - 1, "source vertex");
303	        Validator.validateInRange(destination, 0, vertices - 1, "destination vertex");
304	
305	        if (source == destination) {
306	            throw new IllegalArgumentException("Self-loops are not allowed in a DAG");
307	        }
308	
309	        String edgeKey = source + "->" + destination;
310	        if (edgeSet.contains(edgeKey)) {
311	            throw new IllegalArgumentException("Duplicate edge: " + edgeKey);
312	        }
313	
314	        adjacencyList.get(source).add(destination);
315	        structure.adjacencyList.get(source).add(destination);
316	        edgeSet.add(edgeKey);
317	    }
318	
319	    public TopologicalSortResult topologicalSort() {
320	        if (cachedResult != null) {
321	            return cachedResult;
322	        }
323	        GraphStructure freshStructure = new GraphStructure(vertices, adjacencyList);
324	        cachedResult = algorithm.sort(freshStructure);
325	        isLocked = true;
326	        return cachedResult;
327	    }
